import { ComponentProps } from "react";
import { Meta, StoryObj } from "@storybook/react";
import { action } from "storybook/actions";
import {
  WithMockedDate,
  WithResetQueryCache,
  withMockedDate,
  withQueryProvider,
  withResetQueryCache,
} from "../../../../../../.storybook/preview";
import { DateHelper, throwError } from "@/core/helpers";
import { QueryProvider } from "@/core/providers";
import { expect, userEvent, within } from "storybook/test";
import {
  MOCKED_DATE,
  daysFromToday,
  fetchAlbumMock,
  withFocusedMediaModalMinHeight,
  delay,
  searchForAlbum,
  waitForVisibleElement,
  pasteValue,
  clickOnElement,
} from "../../digital-ride-media-storybook-helpers";
import { SearchAlbumForm } from "./search-album-form";

const ALBUM_WITH_FETCHING_ERROR_ID = "KOL-TOD-ERR-FET";
const PASTED_NONE_MATCHING_FORMAT_ALBUM_ID = "GRO-TOD-NON-PUR";

type StoryArgs = ComponentProps<WithResetQueryCache<WithMockedDate<typeof SearchAlbumForm>>> & {
  existingAlbumsListAction: "ADD_TO_ALBUM" | "GO_TO_ALBUM";
  visitDate: string;
};

/**
 * See `Album Block` stories to view different cases of album data
 *
 * See `Save To Album` stories to view all options/versions for saving media to an album
 */
const meta: Meta<StoryArgs> = {
  title: "Modules/Digital Ride Media/Search Album Form",
  component: SearchAlbumForm,
  argTypes: {
    mockedDate: {
      control: {
        type: "date",
      },
    },
    existingAlbumsListAction: {
      control: "radio",
      options: ["ADD_TO_ALBUM", "GO_TO_ALBUM"],
    },
    visitDate: {
      control: "date",
    },
    albumAction: {
      // this is a complex control based on the controls for `existingAlbumsListAction` and `visitDate`
      table: { disable: true },
    },
  },
  decorators: [withResetQueryCache, withMockedDate, withQueryProvider, withFocusedMediaModalMinHeight],
  parameters: {
    chromatic: { delay: 4000 },
  },
  render: function StoryComponent({ existingAlbumsListAction, visitDate, ...args }: StoryArgs) {
    const sharedProps = {
      service: {
        fetchAlbum: fetchAlbumMock,
        // Functions not needed for the stories
        searchForMedia: () => throwError("Not implemented"),
        createNewAlbumWithInitialMedia: () => throwError("Not implemented"),
        createNewAlbum: () => throwError("Not implemented"),
        fetchAlbumMedia: () => throwError("Not implemented"),
        updateName: () => throwError("Not implemented"),
        addMediaToAlbum: () => throwError("Not implemented"),
        deleteMediaFromAlbum: () => throwError("Not implemented"),
        deleteAlbum: () => throwError("Not implemented"),
        addContactInformationToAlbum: () => throwError("Not implemented"),
        getMediaOnQrCodeAccount: () => throwError("Not implemented"),
        connectQrCodeToAlbum: () => throwError("Not implemented"),
      },
      onClickAlbumResult: (albumId: string) => {
        action("navigateToExistingAlbum")(albumId);
      },
      albumIdInLoadingState: "",
      albumIdInErrorState: "",
      addToAlbumMediaAmount: 0,
    };
    return (
      <QueryProvider>
        <SearchAlbumForm
          {...args}
          {...sharedProps}
          albumAction={
            existingAlbumsListAction === "ADD_TO_ALBUM"
              ? { action: "ADD_TO_ALBUM", visitDate: DateHelper.toStringYYYYMMDD(visitDate) }
              : { action: "GO_TO_ALBUM" }
          }
        />
      </QueryProvider>
    );
  },
};

export default meta;

type Story = StoryObj<typeof meta>;

/** Searches for an existing album by entering its ID.
 * Album is found and shown. */
export const WithGoToAlbumButton: Story = {
  args: {
    mockedDate: new Date(MOCKED_DATE),
    existingAlbumsListAction: "GO_TO_ALBUM",
  },
  play: async ({ canvasElement }) => {
    await searchForAlbum({
      canvasElement,
      albumId: "KOL-TOD-NON-PUR",
    });
    await waitForVisibleElement({
      canvasElement,
      testId: "digital-ride-media-existing-album-KOL-TOD-NON-PUR",
    });
    await waitForVisibleElement({
      canvasElement,
      testId: "digital-ride-media-existing-album-go-to-album-KOL-TOD-NON-PUR",
    });
  },
};

export const WithAddToAlbumButton: Story = {
  args: {
    ...WithGoToAlbumButton.args,
    existingAlbumsListAction: "ADD_TO_ALBUM",
    visitDate: daysFromToday(0),
  },
  play: async ({ canvasElement }) => {
    await searchForAlbum({
      canvasElement,
      albumId: "KOL-TOD-NON-PUR",
    });
    await waitForVisibleElement({
      canvasElement,
      testId: "digital-ride-media-existing-album-KOL-TOD-NON-PUR",
    });
    await waitForVisibleElement({
      canvasElement,
      testId: "digital-ride-media-save-to-existing-album-button-KOL-TOD-NON-PUR",
    });
  },
};

export const WithAddToUnlockedAlbumButton: Story = {
  args: {
    ...WithAddToAlbumButton.args,
  },
  play: async ({ canvasElement }) => {
    await searchForAlbum({
      canvasElement,
      albumId: "KOL-TOD-ALB-UNL",
    });
    await waitForVisibleElement({
      canvasElement,
      testId: "digital-ride-media-existing-album-KOL-TOD-ALB-UNL",
    });
    await waitForVisibleElement({
      canvasElement,
      testId: "digital-ride-media-save-to-existing-unlocked-album-button-KOL-TOD-ALB-UNL",
    });
  },
};

export const WithInvalidAlbumIdInput: Story = {
  args: {
    ...WithGoToAlbumButton.args,
  },
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    const el1 = await canvas.findByTestId("digital-ride-media-search-album-form-album-code-first-part");
    const el2 = await canvas.findByTestId("digital-ride-media-search-album-form-album-code-second-part");
    const el3 = await canvas.findByTestId("digital-ride-media-search-album-form-album-code-third-part");
    await userEvent.type(el1, "1");
    await userEvent.type(el2, "2");
    await userEvent.type(el3, "3");

    clickOnElement({
      canvasElement,
      testId: "digital-ride-media-search-album-form-search-button",
    });

    await waitForVisibleElement({
      canvasElement,
      testId: "digital-ride-media-search-album-form-error",
    });
  },
};

export const WithFetchingError: Story = {
  args: {
    ...WithGoToAlbumButton.args,
  },
  play: async ({ canvasElement }) => {
    await searchForAlbum({
      canvasElement,
      albumId: ALBUM_WITH_FETCHING_ERROR_ID,
    });
    await waitForVisibleElement({
      canvasElement,
      testId: "digital-ride-media-existing-album-KOL-TOD-ERR-FET",
      assert: (el) => expect(el).toHaveAttribute("data-is-error", "true"),
    });
  },
};

export const WithAddToAlbumVisitDateNotMatching: Story = {
  args: {
    ...WithAddToAlbumButton.args,
  },
  play: async ({ canvasElement }) => {
    await searchForAlbum({
      canvasElement,
      albumId: "KOL-LAS-NON-PUR",
    });
    await waitForVisibleElement({
      canvasElement,
      testId: "digital-ride-media-existing-album-KOL-LAS-NON-PUR",
      assert: (el) => expect(el).toHaveAttribute("data-has-visit-date-mismatch", "true"),
    });
  },
};

/** Pastes an album ID matching the park prefix format.
 * ID is split across all three input fields. */
export const WithPasteAlbumIdSplitAcrossFields: Story = {
  args: {
    ...WithGoToAlbumButton.args,
  },
  play: async ({ canvasElement }) => {
    await pasteValue({
      canvasElement,
      testId: "digital-ride-media-search-album-form-album-code-first-part",
      value: "KOL-TOD-NON-PUR",
    });
    await delay(500);
    await waitForVisibleElement({
      canvasElement,
      testId: "digital-ride-media-search-album-form-album-code-first-part",
      assert: (el) => expect(el).toHaveValue("TOD"),
    });
    await waitForVisibleElement({
      canvasElement,
      testId: "digital-ride-media-search-album-form-album-code-second-part",
      assert: (el) => expect(el).toHaveValue("NON"),
    });
    await waitForVisibleElement({
      canvasElement,
      testId: "digital-ride-media-search-album-form-album-code-third-part",
      assert: (el) => expect(el).toHaveValue("PUR"),
    });
    await clickOnElement({
      canvasElement,
      testId: "digital-ride-media-search-album-form-search-button",
    });
  },
};

/** Pastes an album ID with a non-matching park prefix.
 * ID stays in the first field and validation error is shown. */
export const WithPasteNoneMatchingFormatAlbumId: Story = {
  args: {
    ...WithGoToAlbumButton.args,
  },
  play: async ({ canvasElement }) => {
    await pasteValue({
      canvasElement,
      testId: "digital-ride-media-search-album-form-album-code-first-part",
      value: PASTED_NONE_MATCHING_FORMAT_ALBUM_ID,
    });
    await delay(500);
    await waitForVisibleElement({
      canvasElement,
      testId: "digital-ride-media-search-album-form-album-code-first-part",
      assert: (el) => expect(el).toHaveValue(PASTED_NONE_MATCHING_FORMAT_ALBUM_ID),
    });
    await waitForVisibleElement({
      canvasElement,
      testId: "digital-ride-media-search-album-form-album-code-second-part",
      assert: (el) => expect(el).toHaveValue(""),
    });
    await waitForVisibleElement({
      canvasElement,
      testId: "digital-ride-media-search-album-form-album-code-third-part",
      assert: (el) => expect(el).toHaveValue(""),
    });
    await clickOnElement({
      canvasElement,
      testId: "digital-ride-media-search-album-form-search-button",
    });
  },
};
